From 2f4584a06ce7dc332a6a341863f00e09be1d0c76 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sun, 22 Nov 2026 00:27:49 +0100
Subject: [PATCH] notifications: send popups hidden by Do Not Disturb to
 history

Popups on screen when Do Not Disturb turned on were only hidden, so they
popped up again with a fresh timeout once it ended. Mark the ones the
popup model now filters out as expired, so they stay in the history.

BUG: 524749
---
 applets/notifications/global/Globals.qml |  4 +++-
 libnotificationmanager/notifications.cpp | 22 ++++++++++++++++++++++
 libnotificationmanager/notifications.h   |  8 ++++++++
 3 files changed, 33 insertions(+), 1 deletion(-)

diff --git a/applets/notifications/global/Globals.qml b/applets/notifications/global/Globals.qml
index 8e8e56f88d..228fec1c4f 100644
--- a/applets/notifications/global/Globals.qml
+++ b/applets/notifications/global/Globals.qml
@@ -37,7 +37,9 @@ QtObject {
         // so it's not considered "added while inhibited" and shown in history unwanted.
         NotificationManager.Server.inhibited = inhibited;

-        if (!inhibited) {
+        if (inhibited) {
+            popupNotificationsModel.expireInhibitedPopups();
+        } else {
             const urgency = notificationSettings.lowPriorityHistory ? NotificationManager.Notifications.LowUrgency : NotificationManager.Notifications.NormalUrgency;
             popupNotificationsModel.showInhibitionSummary(urgency, notificationSettings.popupBlacklistedApplications, notificationSettings.popupBlacklistedServices);
         }
diff --git a/libnotificationmanager/notifications.cpp b/libnotificationmanager/notifications.cpp
index baa61cecc9..c02fbc5ea5 100644
--- a/libnotificationmanager/notifications.cpp
+++ b/libnotificationmanager/notifications.cpp
@@ -29,6 +29,7 @@
 #include "notificationsortproxymodel_p.h"
 #include "portal_p.h"
 #include "portalnotificationsmodel.h"
+#include "server.h"

 #include "jobsmodel.h"

@@ -1034,6 +1035,27 @@ void Notifications::showInhibitionSummary(Urgency urgency, const QStringList &bl
     d->inhibitionSummaryNotification->sendEvent();
 }

+void Notifications::expireInhibitedPopups()
+{
+    // Wait until the filter settings that depend on the inhibition state have been updated
+    QMetaObject::invokeMethod(
+        this,
+        [this] {
+            if (!Server::self().inhibited()) {
+                return;
+            }
+            for (int i = 0, count = d->notificationsAndJobsModel->rowCount(); i < count; ++i) {
+                const QModelIndex idx = d->notificationsAndJobsModel->index(i, 0);
+                if (idx.data(Notifications::TypeRole).toInt() != Notifications::NotificationType || idx.data(Notifications::ExpiredRole).toBool()
+                    || idx.data(Notifications::DismissedRole).toBool() || d->filterModel->mapFromSource(idx).isValid()) {
+                    continue;
+                }
+                d->notificationsAndJobsModel->setData(idx, true, Notifications::ExpiredRole);
+            }
+        },
+        Qt::QueuedConnection);
+}
+
 void Notifications::hideInhibitionSummary()
 {
     if (d->inhibitionSummaryNotification) {
diff --git a/libnotificationmanager/notifications.h b/libnotificationmanager/notifications.h
index 25b62c1ea0..4c5588621b 100644
--- a/libnotificationmanager/notifications.h
+++ b/libnotificationmanager/notifications.h
@@ -587,6 +587,14 @@ public:
      */
     Q_INVOKABLE void showInhibitionSummary(Urgency urgency, const QStringList &blacklistedDesktopEntries, const QStringList &blacklistedNotifyRcNames);

+    /**
+     * Marks the notifications this model hides while inhibited as expired, so they don't pop up again
+     * once inhibition ends but still show up in the history.
+     *
+     * Call this when inhibition starts. It acts once the filter settings for inhibition have been applied.
+     */
+    Q_INVOKABLE void expireInhibitedPopups();
+
     /**
      * Hides the notification about the number of unread inhibited notifications.
      *
